import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

export default function Page() {
  const dataPromise = getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsLoading />}>
        <DashboardStats dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<RevenueChartLoading />}>
        <DashboardRevenue dataPromise={dataPromise} />
      </Suspense>
      <Suspense fallback={<LatestInvoicesLoading />}>
        <DashboardInvoices dataPromise={dataPromise} />
      </Suspense>
    </main>
  )
}

async function DashboardStats({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const { totalRevenue, totalInvoices } = await dataPromise
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

async function DashboardRevenue({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const { revenue } = await dataPromise
  return <RevenueChart revenue={revenue} />
}

async function DashboardInvoices({ dataPromise }: { dataPromise: Promise<DashboardData> }) {
  const { invoices } = await dataPromise
  return <LatestInvoices invoices={invoices} />
}

function CardStatsLoading() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>Loading revenue...</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>Loading invoices...</p>
      </div>
    </div>
  )
}

function RevenueChartLoading() {
  return (
    <div className="chart" aria-busy="true">
      <h2>Revenue</h2>
      <p>Loading revenue chart...</p>
    </div>
  )
}

function LatestInvoicesLoading() {
  return (
    <div className="invoices" aria-busy="true">
      <h2>Latest Invoices</h2>
      <p>Loading latest invoices...</p>
    </div>
  )
}
